/opt/venv/bin/cadcheck verify model.scad --assembly > /tmp/full.json 2>&1
python3 - <<'EOF'
import json
d=json.load(open('/tmp/full.json'))
for p in d['parts']:
    name=p['part']
    e=p['export']
    sc=e.get('spec_check')
    pr=p.get('printability')
    print('=== PART',name,'ok=',e['ok'],'spec_ok=',sc.get('ok') if sc else None)
    if sc and not sc.get('ok'):
        for k in ('details','bounds','bodies','through_holes','support_faces'):
            v=sc.get(k)
            if isinstance(v,list):
                for row in v:
                    if isinstance(row,dict) and row.get('ok')==False:
                        print('  FAIL',k,row)
            elif isinstance(v,dict) and v.get('ok')==False:
                print('  FAIL',k,v)
    if pr:
        print('  print: undecl=',pr.get('zones_undeclared'), 'in_air=',pr.get('in_the_air'), 'ok-zones:',[(z['id'],z.get('declared'),z.get('bridge',{}).get('bridge_mm')) for z in pr.get('zones',[])])
a=d.get('assembly')
if a:
    import json as j
    print('=== ASSEMBLY ok=',a.get('ok'))
    for k in ('problems','spec_check','motions','assembly_steps','print_in_place','held','instances','copies','pairs'):
        if k in a: print(k,'=',j.dumps(a[k])[:3000])
EOF
